    <div class="inset"><img src="/assets/img/allium.webp" srcset="/assets/img/allium-800.webp 800w, /assets/img/allium.webp 1400w" sizes="(max-width: 900px) 100vw, 50vw" alt="Purple allium flower heads in a green garden" width="1400" height="788" loading="lazy" decoding="async"></div>
  </div>
